 "content": "from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen=set(); objects=[]
    for r in range(h):
        for c in range(w):
            color=grid[r][c]
            if color==0 or (r,c) in seen: continue
            q=deque([(r,c)]); seen.add((r,c)); cells=[]
            while q:
                y,x=q.popleft(); cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<h and 0<=nx<w and (ny,nx) not in seen and grid[ny][nx]==color:
                        seen.add((ny,nx)); q.append((ny,nx))
            a,b=min(y for y,x in cells),max(y for y,x in cells)
            l,rr=min(x for y,x in cells),max(x for y,x in cells)
            crop=[[grid[y][x] for x in range(l,rr+1)] for y in range(a,b+1)]
            objects.append((color,crop,(a,l)))
    # Order the objects by their color and concatenate their tight crops.
    objects.sort(key=lambda o:o[0])
    oh=max(len(o[1]) for o in objects); ow=sum(len(o[1][0]) for o in objects)
    out=[[0]*ow for _ in range(oh)]; off=0
    for color,crop,_ in objects:
        for y,row in enumerate(crop):
            for x,v in enumerate(row): out[y][off+x]=v
        off+=len(crop[0])
    return out
